fn key(s:&str)->Address{s.parse().unwrap()}
fn hex(d:&[u8])->String{d.iter().map(|v|format!("{v:02x}")).collect()}
fn dehex(s:&str)->Vec<u8>{assert_eq!(s.len()%2,0);(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
fn u64at(d:&[u8],n:usize)->u64{u64::from_le_bytes(d[n..n+8].try_into().unwrap())}
fn b64(d:&[u8])->String{let t=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut s=String::new();for c in d.chunks(3){let n=(c[0]as u32)<<16|(c.get(1).copied().unwrap_or(0)as u32)<<8|c.get(2).copied().unwrap_or(0)as u32;s.push(t[(n>>18)as usize]as char);s.push(t[((n>>12)&63)as usize]as char);s.push(if c.len()>1{t[((n>>6)&63)as usize]as char}else{'='});s.push(if c.len()>2{t[(n&63)as usize]as char}else{'='});}s}
fn unb64(s:&str)->Vec<u8>{let t=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=Vec::new();for c in s.as_bytes().chunks(4){let mut n=0u32;for x in c{n=(n<<6)|if *x==b'='{0}else{t.iter().position(|v|v==x).unwrap()as u32};}out.push((n>>16)as u8);if c[2]!=b'='{out.push((n>>8)as u8);}if c[3]!=b'='{out.push(n as u8);}}out}
fn value(a:&Account)->Value{json!({"owner":a.owner.to_string(),"lamports":a.lamports.to_string(),"executable":a.executable,"rentEpoch":a.rent_epoch.to_string(),"data":[b64(&a.data),"base64"]})}
fn row(k:Address,a:Option<Account>)->Value{match a{None=>json!({"address":k.to_string(),"missing":true}),Some(a)=>{let mut v=value(&a);v["address"]=json!(k.to_string());v}}}
fn equal_value(a:&Option<Account>,b:&Option<Account>)->bool{match(a,b){(None,None)=>true,(Some(a),Some(b))=>a.data==b.data&&a.lamports==b.lamports&&a.owner==b.owner&&a.executable==b.executable,_=>false}}
fn immutable_write(path:PathBuf,v:&Value){let bytes=serde_json::to_vec_pretty(v).unwrap();assert!(!path.exists(),"immutable evidence exists: {}",path.display());let mut out=fs::OpenOptions::new().create_new(true).write(true).open(path).unwrap();out.write_all(&bytes).unwrap();out.sync_all().unwrap();}
fn pda(p:Address,parts:&[&[u8]])->Address{Address::find_program_address(parts,&p).0}
async fn bank(program:Address,elf:&[u8],accounts:&BTreeMap<Address,Account>,clock:&Clock)->ProgramTestContext{
 let loader=key("BPFLoaderUpgradeab1e11111111111111111111111");let program_data=pda(loader,&[program.as_ref()]);let mut test=ProgramTest::default();test.prefer_bpf(true);let mut p=2u32.to_le_bytes().to_vec();p.extend_from_slice(program_data.as_ref());let mut d=vec![0;45];d[..4].copy_from_slice(&3u32.to_le_bytes());d.extend_from_slice(elf);
 test.add_genesis_account(program,Account{lamports:10_000_000,data:p,owner:loader,executable:true,rent_epoch:u64::MAX});test.add_genesis_account(program_data,Account{lamports:10_000_000_000,data:d,owner:loader,executable:false,rent_epoch:u64::MAX});for(k,a)in accounts{test.add_genesis_account(*k,a.clone());}let c=test.start_with_context().await;c.set_sysvar(clock);c
}
async fn read(c:&ProgramTestContext,k:Address)->Option<Account>{c.banks_client.get_account(k).await.unwrap()}

